inline void jsonAttrPayload(uint16_t kind,
                           const AttrPayload &payload,
                           std::string &out)
{
    switch (kind) {
    case kAttrKindREPEAT_V1:
        jsonRepeatV1(std::get<RepeatV1>(payload), kind, out);
        break;
    case kAttrKindGEMM_V1:
        jsonGemmV1(std::get<GemmV1>(payload), kind, out);
        break;
    case kAttrKindBMM_V1:
        jsonBmmV1(std::get<BmmV1>(payload), kind, out);
        break;
    case kAttrKindELEMENTWISE_V1:
        jsonElementwiseV1(std::get<ElementwiseV1>(payload), kind, out);
        break;
    case kAttrKindREDUCE_V1:
        jsonReduceV1(std::get<ReduceV1>(payload), kind, out);
        break;
    case kAttrKindSOFTMAX_V1:
        jsonSoftmaxV1(std::get<SoftmaxV1>(payload), kind, out);
        break;
    case kAttrKindNORM_V1:
        jsonNormV1(std::get<NormV1>(payload), kind, out);
        break;
    case kAttrKindFILL_V1:
        jsonFillV1(std::get<FillV1>(payload), kind, out);
        break;
    case kAttrKindBLOCKED_MNK_LAYOUT_V1:
        jsonBlockedMnkLayoutV1(std::get<BlockedMnkLayoutV1>(payload), kind, out);
        break;
    case kAttrKindRECV_WAIT_V1:
        jsonRecvWaitV1(std::get<RecvWaitV1>(payload), kind, out);
        break;
    case kAttrKindFENCE_V1:
        jsonFenceV1(std::get<FenceV1>(payload), kind, out);
        break;
    default:
        out += "null";
        break;
    }
}

static_assert(kHeaderBytes == 128, "header size fixed by spec");
static_assert(kSectionDirBytes == 40, "section dir size fixed by spec");
static_assert(kCommandsBytes == 40, "COMMANDS record fixed by spec");
static_assert(kMoeLayerSpecsBytes == 80, "MOE_LAYER_SPECS record fixed by spec");
static_assert(kMoeExpertSpecsBytes == 40, "MOE_EXPERT_SPECS record fixed by spec");
static_assert(kMoeDynamicRegionsBytes == 72, "MOE_DYNAMIC_REGIONS record fixed by spec");
static_assert(kMoeKernelSpecsBytes == 88, "MOE_KERNEL_SPECS record fixed by spec");

